const creatorStart=titles.length;
titles.push(...creatorLibrary.map(([id,title,creator,genre])=>({title,year:'Official',score:'Official Upload',rating:'YouTube',genre,runtime:'Video',desc:`An official upload from ${creator}’s YouTube channel.`,art:yt(id),embed:`https://www.youtube-nocookie.com/embed/${id}?autoplay=1`,source:`YouTube · ${creator} official channel`,sourceUrl:`https://www.youtube.com/watch?v=${id}`,license:'Standard YouTube copyright terms apply. Watching and embedding are supported; reuse or re-uploading requires permission from the rights holder.'})));
const creatorIndices=[19,20,21,22,...creatorLibrary.map((_,index)=>creatorStart+index)];
const rows=[['Creator Spotlight · Official Uploads',creatorIndices],['Halloween Fright Fest · Free Full Movies',[23,24,25,26,27,28,29,30,31]],['Reaction-Friendly · Creative Commons',[0,1,2,3,4,5,6,7,8]],['Public-Domain Classics',[9,10,12,13,14]],['Silent-Era Essentials',[9,10,11]],['Comedy & Animation',[0,2,4,5,15,16,17,18]],['Adventure Through the Decades',[1,3,6,7,8,13,14,9]],['Short Films',[0,1,2,5,6,7,8,11,15,16,17,18]]];
const catalog=document.querySelector('#catalog');
const cardMarkup=(item,index)=>`<article class="card" tabindex="0" data-details="${index}" aria-label="${item.title}, ${item.genre}"><div class="poster" style="--art:${item.art}"></div><div class="card-copy"><h3>${item.title}</h3><p><span class="match">${item.score}</span> · ${item.year} · ${item.genre}</p></div></article>`;
rows.forEach(([name,indices])=>{const section=document.createElement('section');section.className='rail';section.id=name.startsWith('Reaction')?'new':name.startsWith('Public')?'films':name.startsWith('Comedy')?'series':name==='Short Films'?'list':'';section.innerHTML=`<div class="rail-header"><h2>${name}</h2></div><div class="rail-track">${indices.map(i=>cardMarkup(titles[i],i)).join('')}</div>`;catalog.append(section)});
const topSection=document.createElement('section');topSection.className='rail';topSection.innerHTML=`<h2>Creator Picks</h2><div class="rail-track ranked">${[0,1,2,5,6,7].map((i,n)=>`<article class="rank-card" data-details="${i}" tabindex="0"><div class="rank-number">${n+1}</div>${cardMarkup(titles[i],i)}</article>`).join('')}</div>`;catalog.insertBefore(topSection,catalog.children[2]);
const dialog=document.querySelector('#detailsDialog');let selected=0;const myList=new Set();
function showDetails(index){selected=Number(index);const item=titles[selected];document.querySelector('#detailArt').style.setProperty('--art',item.art);document.querySelector('#detailTitle').textContent=item.title;document.querySelector('#detailMeta').innerHTML=`<span class="match">${item.score}</span><span>${item.year}</span><span class="rating">${item.rating}</span><span>${item.runtime}</span>`;document.querySelector('#detailDescription').textContent=item.desc;document.querySelector('#detailGenres').textContent=`${item.genre} · ${item.source}`;document.querySelector('#detailLicense').textContent=item.license;document.querySelector('#detailSourceLink').href=item.sourceUrl;document.querySelector('#listToggle').textContent=myList.has(selected)?'✓':'＋';dialog.showModal()}
document.addEventListener('click',e=>{const target=e.target.closest('[data-details]');if(target)showDetails(target.dataset.details);const play=e.target.closest('[data-play]');if(play)openPlayer(Number(play.dataset.play))});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-details]')){e.preventDefault();showDetails(e.target.dataset.details)}});
document.querySelector('#closeDetails').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.querySelector('#listToggle').onclick=()=>{myList.has(selected)?myList.delete(selected):myList.add(selected);document.querySelector('#listToggle').textContent=myList.has(selected)?'✓':'＋'};
const player=document.querySelector('#player'),frame=document.querySelector('#playerFrame');function openPlayer(index){const item=titles[index];dialog.close();document.querySelector('#playerTitle').textContent=item.title;document.querySelector('#playerSource').textContent=`${item.source} · ${item.rating}`;frame.src=item.embed;player.hidden=false;document.body.style.overflow='hidden';if(!document.fullscreenElement&&player.requestFullscreen)player.requestFullscreen().catch(()=>{})}document.querySelector('#dialogPlay').onclick=()=>openPlayer(selected);document.querySelector('#closePlayer').onclick=()=>{frame.src='about:blank';player.hidden=true;document.body.style.overflow='';if(document.fullscreenElement)document.exitFullscreen().catch(()=>{})};document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&!player.hidden){frame.src='about:blank';player.hidden=true;document.body.style.overflow=''}});
const search=document.querySelector('#searchPanel'),input=document.querySelector('#searchInput'),results=document.querySelector('#searchResults'),status=document.querySelector('#searchStatus');function renderSearch(query=''){const q=query.trim().toLowerCase().replace(/science[ -]?fiction/g,'sci-fi');const matches=q?titles.filter(t=>`${t.title} ${t.genre} ${t.desc} ${t.source} ${t.license}`.toLowerCase().includes(q)):titles;status.textContent=q?`${matches.length} result${matches.length===1?'':'s'} for “${query}”`:'Browse official creator uploads, open films, and public-domain classics';results.innerHTML=matches.map(t=>cardMarkup(t,titles.indexOf(t))).join('')}
document.querySelector('#searchButton').onclick=()=>{search.hidden=false;document.body.style.overflow='hidden';renderSearch();setTimeout(()=>input.focus(),0)};document.querySelector('#closeSearch').onclick=()=>{search.hidden=true;document.body.style.overflow=''};input.addEventListener('input',e=>renderSearch(e.target.value));document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!search.hidden){search.hidden=true;document.body.style.overflow=''}else if(!player.hidden){frame.src='about:blank';player.hidden=true;document.body.style.overflow=''}}});window.addEventListener('scroll',()=>document.querySelector('#topbar').classList.toggle('scrolled',scrollY>30),{passive:true});
